mapper.select:
SELECT e.no,e.title,e.open_date,e.close_date,e.instructor_id,
       NVL(e.time_limit,120) AS time_limit,
       (SELECT COUNT(*) FROM scheduled_exam_map WHERE exam_no=e.no) AS question_count
FROM scheduled_exam e
WHERE e.no=#{examNo}
  AND e.instructor_id=#{instructorId}

SELECT m.question_no
FROM scheduled_exam_map m
	JOIN scheduled_exam e ON m.exam_no=e.no
WHERE m.exam_no=#{examNo}
  AND e.instructor_id=#{instructorId}
ORDER BY m.no

SELECT no,title,score,type,theme FROM exam_question
WHERE theme=#{theme}
ORDER BY theme,no

mapper.insert:
INSERT INTO scheduled_exam_map(exam_no,question_no)
SELECT data.* FROM (

	SELECT #{item.exam_no},#{item.question_no}
	FROM dual

) data

mapper.update:
UPDATE scheduled_exam
SET title=#{title},
    open_date=#{open_date},
    close_date=#{close_date},
    time_limit=#{time_limit}
WHERE no=#{no}
  AND instructor_id=#{instructor_id}
  AND open_date>SYSDATE

UPDATE scheduled_exam
SET close_date=#{close_date}
WHERE no=#{no}
  AND instructor_id=#{instructor_id}
  AND open_date<=SYSDATE
  AND close_date>SYSDATE

mapper.select:
SELECT COUNT(*)
FROM exam_enrollment
WHERE exam_no=#{examNo}

mapper.delete:
DELETE FROM scheduled_exam
WHERE no=#{examNo}
  AND instructor_id=#{instructorId}
  AND open_date>SYSDATE
